fn sum(v: &[i64]) -> i64 {
    if v.len() < 1024 { return v.iter().sum(); }      // leaf
    let (lo, hi) = v.split_at(v.len() / 2);
    let (a, b) = rayon::join(|| sum(lo), || sum(hi)); // fork + join (work stealing)
    a + b
}

